-- Smash history: the P+ (Project M) and Smash 4 brackets missing from 12 start.gg majors of 2017-2019. Their
-- main brackets weren't on start.gg (the P+ ones were often run apart from the rest of the tournament), so
-- nothing was saved for that game. Added by hand from each bracket's own Liquipedia page (Matthew, 2026-11-19:
-- "continue with history from liquipedia"), read in Matthew's Chrome about 8 seconds apart: player count and
-- top 8 only, credited to that page (CC-BY-SA). Only brackets Liquipedia rates Major or Premier.
-- Event ids start with "manual-" so the start.gg jobs leave them alone (isManualEvent). Safe to run twice:
-- an existing bracket isn't touched, and a major that already has a bracket of that game is skipped.

insert into public.major_events (major_slug, event_id, game, name, entrants, top8)
select v.major_slug, v.event_id, v.game, v.name, v.entrants, v.top8
from (values
  ('smash-n-splash-3', 'manual-pplus-1', 'pplus', 'P+ Singles', 319, '[{"place":1,"name":"Switch","playerId":null},{"place":2,"name":"Sothe","playerId":null},{"place":3,"name":"lloD","playerId":null},{"place":4,"name":"Phresh","playerId":null},{"place":5,"name":"HyperFlame","playerId":null},{"place":5,"name":"techboy","playerId":null},{"place":7,"name":"Lunchables","playerId":null},{"place":7,"name":"Dirtboy","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Smash_%27N%27_Splash/3/Project_M'),
  ('low-tier-city-5', 'manual-pplus-1', 'pplus', 'P+ Singles', 201, '[{"place":1,"name":"Malachi","playerId":null},{"place":2,"name":"ThundeRzReiGN","playerId":null},{"place":3,"name":"Twisty","playerId":null},{"place":4,"name":"dvd","playerId":null},{"place":5,"name":"Fuzz","playerId":null},{"place":5,"name":"Phresh","playerId":null},{"place":7,"name":"Sosa","playerId":null},{"place":7,"name":"Switch","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Low_Tier_City/5/Project_M'),
  ('shine-2017', 'manual-smash4-1', 'smash4', 'Smash 4 Singles', 658, '[{"place":1,"name":"ZeRo","playerId":null},{"place":2,"name":"Tweek","playerId":null},{"place":3,"name":"Nairo","playerId":null},{"place":4,"name":"Salem","playerId":null},{"place":5,"name":"Ally","playerId":null},{"place":5,"name":"MKLeo","playerId":null},{"place":7,"name":"komorikiri","playerId":null},{"place":7,"name":"Larry Lurr","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Shine/2017/Wii_U'),
  ('we-tech-those-3', 'manual-pplus-1', 'pplus', 'P+ Singles', 194, '[{"place":1,"name":"Switch","playerId":null},{"place":2,"name":"Malachi","playerId":null},{"place":3,"name":"dvd","playerId":null},{"place":4,"name":"Aidan","playerId":null},{"place":5,"name":"Sothe","playerId":null},{"place":5,"name":"Kycse","playerId":null},{"place":7,"name":"techboy","playerId":null},{"place":7,"name":"StereoKiDD","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/We_Tech_Those/3/Project_M'),
  ('the-flex-zone-3', 'manual-pplus-1', 'pplus', 'P+ Singles', 93, '[{"place":1,"name":"Sosa","playerId":null},{"place":2,"name":"Fuzz","playerId":null},{"place":3,"name":"Switch","playerId":null},{"place":4,"name":"Kycse","playerId":null},{"place":5,"name":"dvd","playerId":null},{"place":5,"name":"Malachi","playerId":null},{"place":7,"name":"Yung Quaff","playerId":null},{"place":7,"name":"Silver","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/The_Flex_Zone/3'),
  ('smash-n-splash-4', 'manual-pplus-1', 'pplus', 'P+ Singles', 352, '[{"place":1,"name":"Lunchables","playerId":null},{"place":2,"name":"Switch","playerId":null},{"place":3,"name":"HyperFlame","playerId":null},{"place":4,"name":"Sothe","playerId":null},{"place":5,"name":"Rongunshu","playerId":null},{"place":5,"name":"Kycse","playerId":null},{"place":7,"name":"Junebug","playerId":null},{"place":7,"name":"techboy","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Smash_%27N%27_Splash/4/Project_M'),
  ('2gg-hyrule-saga', 'manual-smash4-1', 'smash4', 'Smash 4 Singles', 780, '[{"place":1,"name":"Tweek","playerId":null},{"place":2,"name":"Mr.R","playerId":null},{"place":3,"name":"Dabuz","playerId":null},{"place":4,"name":"ANTi","playerId":null},{"place":5,"name":"Cosmos","playerId":null},{"place":5,"name":"CaptainZack","playerId":null},{"place":7,"name":"SDX","playerId":null},{"place":7,"name":"MkLeo","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/2GG/Hyrule_Saga'),
  ('the-even-bigger-balc', 'manual-pplus-1', 'pplus', 'P+ Singles', 427, '[{"place":1,"name":"ThundeRzReiGN","playerId":null},{"place":2,"name":"Sosa","playerId":null},{"place":3,"name":"Blank","playerId":null},{"place":4,"name":"techboy","playerId":null},{"place":5,"name":"BaconPancakes","playerId":null},{"place":5,"name":"Envy","playerId":null},{"place":7,"name":"Fuzz","playerId":null},{"place":7,"name":"Boringman","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/The_Big_Balc/3/Project_M'),
  ('kumite-in-texas-low-tier-city-6', 'manual-pplus-1', 'pplus', 'P+ Singles', 177, '[{"place":1,"name":"Sosa","playerId":null},{"place":2,"name":"Malachi","playerId":null},{"place":3,"name":"BaconPancakes","playerId":null},{"place":4,"name":"Morsecode762","playerId":null},{"place":5,"name":"Pikmon","playerId":null},{"place":5,"name":"Flipp","playerId":null},{"place":7,"name":"HyperFlame","playerId":null},{"place":7,"name":"The Doctor","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Low_Tier_City/6/Project_M'),
  ('blacklisted-4', 'manual-pplus-1', 'pplus', 'P+ Singles', 137, '[{"place":1,"name":"Switch","playerId":null},{"place":2,"name":"Filthy Casual","playerId":null},{"place":3,"name":"techboy","playerId":null},{"place":4,"name":"Envy","playerId":null},{"place":5,"name":"dvd","playerId":null},{"place":5,"name":"Flipp","playerId":null},{"place":7,"name":"Twisty","playerId":null},{"place":7,"name":"Pikmon","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Blacklisted/4'),
  ('smash-n-splash-5', 'manual-pplus-1', 'pplus', 'P+ Singles', 392, '[{"place":1,"name":"Malachi","playerId":null},{"place":2,"name":"techboy","playerId":null},{"place":3,"name":"ThundeRzReiGN","playerId":null},{"place":4,"name":"Pikmon","playerId":null},{"place":5,"name":"Switch","playerId":null},{"place":5,"name":"Aki","playerId":null},{"place":7,"name":"Drugfreechu","playerId":null},{"place":7,"name":"The Doctor","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Smash_%27N%27_Splash/5/Project_M'),
  ('low-tier-city-7', 'manual-pplus-1', 'pplus', 'P+ Singles', 130, '[{"place":1,"name":"ThundeRzReiGN","playerId":null},{"place":2,"name":"Morsecode762","playerId":null},{"place":3,"name":"Fuzz","playerId":null},{"place":4,"name":"Dirtboy","playerId":null},{"place":5,"name":"Poilu","playerId":null},{"place":5,"name":"Sneez","playerId":null},{"place":7,"name":"DrinkingFood","playerId":null},{"place":7,"name":"American Bowser","playerId":null}]'::jsonb, 'https://liquipedia.net/smash/Low_Tier_City/7/Project_M')
) as v (major_slug, event_id, game, name, entrants, top8, source_url)
where exists (select 1 from public.majors m where m.slug = v.major_slug)
  and not exists (
    select 1 from public.major_events e
    where e.major_slug = v.major_slug and e.game = v.game and not e.teams and jsonb_array_length(e.top8) > 0
  )
on conflict (major_slug, event_id) do nothing;
